    Bug 1972819 - Fix intermittent comm/mail/test/browser/folder-display/browser_messageWindow.js | Message should have been marked read! - false == true. r=vineet

    Give the keyboard event time to occur before checking.

    Differential Revision: https://phabricator.services.mozilla.com/D273185

diff --git a/mail/test/browser/folder-display/browser_messageWindow.js b/mail/test/browser/folder-display/browser_messageWindow.js
index 7feb7bf3530..6975974be30 100644
--- a/mail/test/browser/folder-display/browser_messageWindow.js
+++ b/mail/test/browser/folder-display/browser_messageWindow.js
@@ -84,19 +84,25 @@ add_task(async function test_open_message_window() {
     await TestUtils.waitForCondition(
       () => msgc.window.document.title == expectedTitle
     );
-    Assert.equal(msgc.window.document.title, expectedTitle);
+    Assert.equal(
+      msgc.window.document.title,
+      expectedTitle,
+      "title should be correct"
+    );
   }
 });

 /**
  * Use the "m" keyboard accelerator to mark a message as read or unread.
  */
-add_task(function test_toggle_read() {
+add_task(async function test_toggle_read() {
   curMessage.markRead(false);
   EventUtils.synthesizeKey("m", {}, msgc);
+  await TestUtils.waitForTick();
   Assert.ok(curMessage.isRead, "Message should have been marked read!");

   EventUtils.synthesizeKey("m", {}, msgc);
+  await TestUtils.waitForTick();
   Assert.ok(!curMessage.isRead, "Message should have been marked unread!");
 });
